const http = require('http');
const zlib = require('zlib');

const PORT = Number(process.env.PORT || 10000);
const SYSTEM = `Sen ALLES AI'sın. Türkçe başta olmak üzere kullanıcının dilinde doğal, doğru, yararlı ve doğrudan cevap ver. Kendini başka bir markanın asistanı olarak tanıtma. ALLES AI, bir Türk genci ve ekibinin özverili çalışmaları sonucu oluşturulmuş bir sistemdir. Bilgi zamanın 2026 Eylül dönemine kadar günceldir; özellikle 2026 Mayıs ve sonrasındaki tarihli olaylarda mümkünse web aramasıyla doğrula, emin olmadığın bilgiyi kesinmiş gibi uydurma. 30 Eylül 2026 sonrasını güncel gerçek olarak sunma. Markdown kalın/italik için yıldız işareti kullanma; kelimelerin başına veya sonuna * ya da ** koyma. Kod bloklarında gereken karakterleri aynen koru. Cevaplarda konuya uygun emojileri doğal biçimde ve daha sık kullan; fakat emoji adlarını yazma veya seslendirme. Kod istendiğinde gerçekten çalışan ve mümkün olduğunca eksiksiz kod ver. Ekli görsel veya dosya sağlanmışsa yalnızca dosya adına bakma; sana aktarılan gerçek görseli, PDF'yi veya dosya metnini incele ve cevabını içeriğe dayandır. İçeriği gerçekten alamadıysan gördüğünü uydurma. Görsel çizme isteği /api/image tarafından ele alınır.`;

const HTML_GZIP_B64 = '';
let HTML_CACHE = null;
function getHtml(){
  if(!HTML_CACHE) HTML_CACHE = zlib.gunzipSync(Buffer.from(HTML_GZIP_B64,'base64'));
  return HTML_CACHE;
}

const hits = new Map();
function rateOkay(ip){
  const now=Date.now(), windowMs=60000, max=Number(process.env.ALLES_RATE_LIMIT||20);
  let x=hits.get(ip);
  if(!x || now-x.start>=windowMs) x={start:now,count:0};
  x.count++; hits.set(ip,x);
  if(hits.size>5000){ for(const [k,v] of hits) if(now-v.start>windowMs*2) hits.delete(k); }
  return x.count<=max;
}
function sendJson(res,status,obj){
  const body=Buffer.from(JSON.stringify(obj));
  res.writeHead(status,{'Content-Type':'application/json; charset=utf-8','Content-Length':body.length,'Cache-Control':'no-store'});
  res.end(body);
}
function sendHtml(res,headOnly=false){
  const body=getHtml();
  res.writeHead(200,{'Content-Type':'text/html; charset=utf-8','Content-Length':body.length,'Cache-Control':'public, max-age=300'});
  res.end(headOnly?undefined:body);
}
function readJson(req,limit=32*1024*1024){
  return new Promise((resolve,reject)=>{
    let size=0; const chunks=[];
    req.on('data',c=>{ size+=c.length; if(size>limit){reject(new Error('PAYLOAD_TOO_LARGE')); req.destroy(); return;} chunks.push(c); });
    req.on('end',()=>{ try{ resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')||'{}')); }catch{ reject(new Error('INVALID_JSON')); } });
    req.on('error',reject);
  });
}
function safeHistory(v){
  if(!Array.isArray(v))return [];
  return v.slice(-12).map(m=>({role:m?.role==='assistant'?'assistant':'user',content:String(m?.content||'').slice(0,12000)})).filter(m=>m.content.trim());
}
function safeAttachments(v){
  if(!Array.isArray(v))return [];
  let total=0;
  const out=[];
  for(const raw of v.slice(0,5)){
    const kind=String(raw?.kind||'').toLowerCase();
    if(!['image','pdf','docx','text'].includes(kind))continue;
    const name=String(raw?.name||'dosya').slice(0,220);
    const size=Math.max(0,Number(raw?.size||0)||0);
    total+=size;if(total>15*1024*1024)break;
    const a={kind,name,size};
    if(kind==='image'||kind==='pdf'){
      a.mime=String(raw?.mime||(kind==='pdf'?'application/pdf':'image/jpeg')).slice(0,100);
      a.data=String(raw?.data||'');
      if(!a.data||a.data.length>12*1024*1024*1.5)continue;
    }else{
      a.text=String(raw?.text||'').slice(0,90000);
      if(!a.text.trim())continue;
    }
    out.push(a);
  }
  return out;
}
function hasImageAttachments(list){return (list||[]).some(a=>a.kind==='image')}
function hasPdfAttachments(list){return (list||[]).some(a=>a.kind==='pdf')}
function hasBinaryAttachments(list){return hasImageAttachments(list)||hasPdfAttachments(list)}
function geminiAttachmentParts(list){
  const parts=[];
  for(const a of (list||[])){
    if((a.kind==='image'||a.kind==='pdf')&&a.data)parts.push({inlineData:{mimeType:a.mime||'application/octet-stream',data:a.data}});
    else if(a.text)parts.push({text:`[Eklenen dosya: ${a.name}]
${a.text}`});
  }
  return parts;
}
function openAIAttachmentPartsServer(list){
  const parts=[];
  for(const a of (list||[])){
    if(a.kind==='image'&&a.data)parts.push({type:'input_image',image_url:`data:${a.mime||'image/jpeg'};base64,${a.data}`,detail:'auto'});
    else if(a.kind==='pdf'&&a.data)parts.push({type:'input_file',filename:a.name||'dosya.pdf',file_data:`data:application/pdf;base64,${a.data}`});
    else if(a.text)parts.push({type:'input_text',text:`[Eklenen dosya: ${a.name}]
${a.text}`});
  }
  return parts;
}
function claudeAttachmentPartsServer(list){
  const parts=[];
  for(const a of (list||[])){
    if(a.kind==='image'&&a.data)parts.push({type:'image',source:{type:'base64',media_type:a.mime||'image/jpeg',data:a.data}});
    else if(a.kind==='pdf'&&a.data)parts.push({type:'document',source:{type:'base64',media_type:'application/pdf',data:a.data}});
    else if(a.text)parts.push({type:'text',text:`[Eklenen dosya: ${a.name}]
${a.text}`});
  }
  return parts;
}
function compatibleUserContentServer(name,text,list){
  if(!list?.length)return text;
  const parts=[];
  for(const a of list){
    if(a.text)parts.push({type:'text',text:`[Eklenen dosya: ${a.name}]
${a.text}`});
    else if(a.kind==='image'&&a.data&&['Grok','OpenRouter'].includes(name))parts.push({type:'image_url',image_url:{url:`data:${a.mime||'image/jpeg'};base64,${a.data}`}});
  }
  parts.push({type:'text',text});
  return parts.length===1?text:parts;
}
async function fetchJSON(url,opts,timeout=75000){
  const ctrl=new AbortController(); const timer=setTimeout(()=>ctrl.abort(),timeout);
  try{
    const r=await fetch(url,{...opts,signal:ctrl.signal});
    const raw=await r.text(); let j={}; try{j=JSON.parse(raw)}catch{}
    if(!r.ok)throw new Error(j?.error?.message||j?.message||raw||`HTTP ${r.status}`);
    return j;
  }finally{clearTimeout(timer)}
}
function needsFreshInfo(text){
  return /(2026|güncel|guncel|bugün|bugun|şu an|su an|en son|son durum|haber|mayıs|mayis|haziran|temmuz|ağustos|agustos|eylül|eylul|transfer|maç|mac|seçim|secim|fiyat|kur|başkan|baskan|kim kazandı|kim kazandi)/i.test(String(text||''));
}
function cleanAssistantText(text){
  const src=String(text||'').trim();
  if(!src)return src;
  const parts=src.split(/(```[\s\S]*?```)/g);
  let out=parts.map(p=>{
    if(p.startsWith('```'))return p;
    return p
      .replace(/^\s*\*\s+/gm,'• ')
      .replace(/\*\*([^*\n]+)\*\*/g,'$1')
      .replace(/__([^_\n]+)__/g,'$1')
      .replace(/\*([^*\n]+)\*/g,'$1')
      .replace(/_([^_\n]+)_/g,'$1')
      .replace(/\*\*/g,'');
  }).join('').trim();
  const hasEmoji=/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/u.test(out);
  if(out&&!hasEmoji&&!out.includes('```'))out+=' ✨';
  return out;
}
function finalizeChatResult(result){
  return {...result,answer:cleanAssistantText(result?.answer||'')};
}
function asTranscript(history,text){
  const h=history.map(m=>`${m.role==='assistant'?'ALLES AI':'Kullanıcı'}: ${m.content}`).join('\n');
  return `${SYSTEM}\n\n${h}${h?'\n':''}Kullanıcı: ${text}\nALLES AI:`;
}
async function askGemini(text,history,attachments=[]){
  const key=process.env.GEMINI_API_KEY; if(!key)throw new Error('GEMINI_API_KEY yok');
  const model=process.env.GEMINI_MODEL||'gemini-3.8-flash';
  const contents=history.map(m=>({role:m.role==='assistant'?'model':'user',parts:[{text:m.content}]}));
  contents.push({role:'user',parts:[{text},...geminiAttachmentParts(attachments)]});
  const baseBody={systemInstruction:{parts:[{text:SYSTEM}]},contents,generationConfig:{temperature:.65,maxOutputTokens:8192}};
  let lastErr=null;
  for(const withSearch of [true,false]){
    try{
      const body=withSearch?{...baseBody,tools:[{google_search:{}}]}:baseBody;
      const j=await fetchJSON(`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`,{method:'POST',headers:{'Content-Type':'application/json','x-goog-api-key':key},body:JSON.stringify(body)},120000);
      const answer=(j?.candidates?.[0]?.content?.parts||[]).map(p=>p.text||'').join('').trim(); if(!answer)throw new Error('Gemini boş yanıt döndürdü');
      return {answer,provider:withSearch?'Gemini · Google Search':'Gemini',model};
    }catch(e){lastErr=e}
  }
  throw lastErr||new Error('Gemini yanıt veremedi');
}
function extractOpenAIResponse(j){
  if(typeof j?.output_text==='string'&&j.output_text.trim())return j.output_text.trim();
  const out=[]; for(const item of (j?.output||[]))for(const c of (item?.content||[]))if(typeof c?.text==='string')out.push(c.text); return out.join('\n').trim();
}
async function askOpenAI(text,history,attachments=[]){
  const key=process.env.OPENAI_API_KEY; if(!key)throw new Error('OPENAI_API_KEY yok');
  const model=process.env.OPENAI_MODEL||'gpt-5.6-luna';
  const input=history.map(m=>({role:m.role==='assistant'?'assistant':'user',content:[{type:'input_text',text:m.content}]}));
  input.push({role:'user',content:[{type:'input_text',text},...openAIAttachmentPartsServer(attachments)]});
  const base={model,instructions:SYSTEM,input,max_output_tokens:8192,store:false};
  const attempts=needsFreshInfo(text)?[{...base,tools:[{type:'web_search'}]},base]:[base];
  let lastErr=null;
  for(const payload of attempts){
    try{
      const j=await fetchJSON('https://api.openai.com/v1/responses',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+key},body:JSON.stringify(payload)},120000);
      const answer=extractOpenAIResponse(j); if(!answer)throw new Error('OpenAI boş yanıt döndürdü');
      return {answer,provider:payload.tools?'OpenAI · Web Search':'OpenAI',model};
    }catch(e){lastErr=e}
  }
  throw lastErr||new Error('OpenAI yanıt veremedi');
}
async function askAnthropic(text,history,attachments=[]){
  const key=process.env.CLAUDE_API_KEY; if(!key)throw new Error('CLAUDE_API_KEY yok');
  const model=process.env.CLAUDE_MODEL||'claude-sonnet-4-6';
  const messages=history.map(m=>({role:m.role==='assistant'?'assistant':'user',content:m.content}));
  const content=[...claudeAttachmentPartsServer(attachments),{type:'text',text}];
  messages.push({role:'user',content:attachments.length?content:text});
  const j=await fetchJSON('https://api.anthropic.com/v1/messages',{method:'POST',headers:{'Content-Type':'application/json','x-api-key':key,'anthropic-version':'2023-06-01'},body:JSON.stringify({model,system:SYSTEM,messages,max_tokens:8192})},120000);
  const answer=(j?.content||[]).map(x=>x?.text||'').join('').trim(); if(!answer)throw new Error('Claude boş yanıt döndürdü'); return {answer,provider:'Claude',model};
}
async function askCompatible({name,key,base,model,text,history,attachments=[],headers={}}){
  if(!key)throw new Error(`${name} anahtarı yok`);
  if(hasPdfAttachments(attachments))throw new Error(`${name} PDF içeriğini bu bağlantı yolunda güvenilir biçimde okuyamıyor`);
  const messages=[{role:'system',content:SYSTEM},...history];
  messages.push({role:'user',content:compatibleUserContentServer(name,text,attachments)});
  const j=await fetchJSON(base,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+key,...headers},body:JSON.stringify({model,messages,temperature:.65,max_tokens:8192})},120000);
  let content=j?.choices?.[0]?.message?.content;
  if(Array.isArray(content))content=content.map(x=>x?.text||'').join('\n');
  const answer=String(content||'').trim(); if(!answer)throw new Error(`${name} boş yanıt döndürdü`); return {answer,provider:name,model};
}
async function handleChat(body){
  const text=String(body?.text||'').trim(), history=safeHistory(body?.history), attachments=safeAttachments(body?.attachments);
  if(!text){const e=new Error('Mesaj boş.');e.status=400;throw e} if(text.length>20000){const e=new Error('Mesaj çok uzun.');e.status=413;throw e}
  const providers=[
    ()=>askGemini(text,history,attachments),
    ()=>askOpenAI(text,history,attachments),
    ()=>askAnthropic(text,history,attachments)
  ];
  if(!hasPdfAttachments(attachments)){
    providers.push(()=>askCompatible({name:'Grok',key:process.env.GROK_API_KEY,base:'https://api.x.ai/v1/chat/completions',model:process.env.GROK_MODEL||'grok-4-fast',text,history,attachments}));
    if(!hasImageAttachments(attachments)){
      providers.push(()=>askCompatible({name:'DeepSeek',key:process.env.DEEPSEEK_API_KEY,base:'https://api.deepseek.com/chat/completions',model:process.env.DEEPSEEK_MODEL||'deepseek-chat',text,history,attachments}));
      providers.push(()=>askCompatible({name:'Mistral',key:process.env.MISTRAL_API_KEY,base:'https://api.mistral.ai/v1/chat/completions',model:process.env.MISTRAL_MODEL||'mistral-small-latest',text,history,attachments}));
      providers.push(()=>askCompatible({name:'Perplexity',key:process.env.PERPLEXITY_API_KEY,base:'https://api.perplexity.ai/chat/completions',model:process.env.PERPLEXITY_MODEL||'sonar',text,history,attachments}));
    }
    providers.push(()=>askCompatible({name:'OpenRouter',key:process.env.OPENROUTER_API_KEY,base:'https://openrouter.ai/api/v1/chat/completions',model:process.env.OPENROUTER_MODEL||'openai/gpt-5.6-luna',text,history,attachments,headers:{'HTTP-Referer':process.env.PUBLIC_URL||'https://alles-ai.onrender.com','X-Title':'ALLES AI'}}));
  }
  let last=attachments.length?'Ekli dosyayı görebilen sağlayıcı bulunamadı.':'Sunucuda hiçbir AI anahtarı tanımlı değil.';
  for(const run of providers){try{return finalizeChatResult(await run())}catch(e){last=String(e?.message||e)}}
  const e=new Error((attachments.length?'Ekli görsel/dosya içeriği okunamadı. ':'Bağlı AI sağlayıcıları yanıt veremedi. ')+last);e.status=503;throw e;
}
function crc32(buf){
  let c=0xffffffff;
  for(const b of buf){c^=b;for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xedb88320:0)}
  return (c^0xffffffff)>>>0;
}
function pngChunk(type,data){
  const t=Buffer.from(type,'ascii'), d=Buffer.from(data||[]), out=Buffer.alloc(12+d.length);
  out.writeUInt32BE(d.length,0);t.copy(out,4);d.copy(out,8);out.writeUInt32BE(crc32(Buffer.concat([t,d])),8+d.length);return out;
}
function makePixelArtPng(prompt){
  const W=160,H=96,pix=Buffer.alloc(W*H*3);
  let h=2166136261;for(const ch of String(prompt||'')){h^=ch.codePointAt(0);h=Math.imul(h,16777619)>>>0}
  const rgb=(r,g,b)=>[Math.max(0,Math.min(255,r|0)),Math.max(0,Math.min(255,g|0)),Math.max(0,Math.min(255,b|0))];
  const set=(x,y,c)=>{if(x<0||y<0||x>=W||y>=H)return;const i=(y*W+x)*3;pix[i]=c[0];pix[i+1]=c[1];pix[i+2]=c[2]};
  const rect=(x,y,w,hh,c)=>{for(let yy=y;yy<y+hh;yy++)for(let xx=x;xx<x+w;xx++)set(xx,yy,c)};
  const circ=(cx,cy,r,c)=>{for(let y=cy-r;y<=cy+r;y++)for(let x=cx-r;x<=cx+r;x++)if((x-cx)*(x-cx)+(y-cy)*(y-cy)<=r*r)set(x,y,c)};
  const tri=(cx,base,half,height,c)=>{for(let y=0;y<height;y++){const hw=Math.max(1,Math.round(half*(y/height)));rect(cx-hw,base-height+y,hw*2+1,1,c)}};
  const sky1=rgb(40+(h&31),120+((h>>5)&31),190+((h>>10)&31));
  const sky2=rgb(115+((h>>15)&31),180+((h>>20)&31),225);
  for(let y=0;y<H;y++){const t=y/H;rect(0,y,W,1,rgb(sky1[0]*(1-t)+sky2[0]*t,sky1[1]*(1-t)+sky2[1]*t,sky1[2]*(1-t)+sky2[2]*t))}
  const q=String(prompt||'').toLocaleLowerCase('tr-TR');
  if(/dağ|dag|mountain|doğa|doga|nature|orman|forest|manzara/.test(q)){
    circ(128,20,9,rgb(255,220,90));
    rect(0,69,W,27,rgb(55,135,70));
    tri(48,72,43,48,rgb(70,88,115));tri(101,73,50,58,rgb(82,98,125));tri(140,74,30,39,rgb(64,82,105));
    tri(48,47,10,11,rgb(235,240,245));tri(101,35,12,14,rgb(240,245,250));
    for(let x=6;x<155;x+=11){const th=7+((x*13+h)%9);rect(x,65-th,2,th,rgb(92,60,35));tri(x+1,65-th+2,5,11,rgb(28,100,54))}
  }else if(/araba|otomobil|car|vehicle|spor araba/.test(q)){
    rect(0,60,W,36,rgb(54,58,64));rect(0,75,W,3,rgb(240,220,80));
    const body=rgb(185+((h>>2)&55),40+((h>>9)&60),45+((h>>17)&50));
    rect(40,50,82,22,body);rect(59,39,43,15,body);rect(65,42,14,9,rgb(120,190,220));rect(82,42,14,9,rgb(120,190,220));
    circ(58,73,10,rgb(25,25,28));circ(108,73,10,rgb(25,25,28));circ(58,73,4,rgb(170,170,175));circ(108,73,4,rgb(170,170,175));
    rect(119,55,6,5,rgb(255,235,150));
  }else if(/futbol|football|soccer|top|ball/.test(q)){
    rect(0,55,W,41,rgb(48,145,70));circ(80,50,28,rgb(238,238,238));circ(80,50,8,rgb(30,30,35));
    for(const [x,y] of [[65,38],[96,39],[63,59],[96,62],[80,72]])circ(x,y,5,rgb(35,35,40));
    rect(12,30,3,40,rgb(240,240,240));rect(12,30,28,3,rgb(240,240,240));rect(37,30,3,40,rgb(240,240,240));
  }else{
    for(let by=18;by<84;by+=8)for(let bx=12;bx<148;bx+=8){const n=(Math.imul((bx+1)*(by+3),1103515245)+h)>>>0;rect(bx,by,7,7,rgb(45+(n&127),45+((n>>8)&127),45+((n>>16)&127)))}
    circ(80,48,20,rgb(235,235,245));circ(80,48,11,rgb(70+(h&80),70+((h>>8)&80),140+((h>>16)&80)));
  }
  const raw=Buffer.alloc((W*3+1)*H);for(let y=0;y<H;y++){raw[y*(W*3+1)]=0;pix.copy(raw,y*(W*3+1)+1,y*W*3,(y+1)*W*3)}
  const ihdr=Buffer.alloc(13);ihdr.writeUInt32BE(W,0);ihdr.writeUInt32BE(H,4);ihdr[8]=8;ihdr[9]=2;ihdr[10]=0;ihdr[11]=0;ihdr[12]=0;
  const png=Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),pngChunk('IHDR',ihdr),pngChunk('IDAT',zlib.deflateSync(raw,{level:9})),pngChunk('IEND',Buffer.alloc(0))]);
  return 'data:image/png;base64,'+png.toString('base64');
}
async function imageOpenAI(prompt){
  const key=process.env.OPENAI_API_KEY;if(!key)throw new Error('OPENAI_API_KEY yok');
  const model=process.env.OPENAI_IMAGE_MODEL||'gpt-image-2';
  const enhanced=`Yüksek kaliteli, ayrıntılı, doğal ışık, güçlü kompozisyon, temiz detaylar. Kullanıcı isteğini sadık biçimde görselleştir: ${prompt}`;
  const variants=[{model,prompt:enhanced,size:'1536x1024',quality:'high',n:1},{model,prompt:enhanced,size:'1024x1024',quality:'high',n:1},{model,prompt:enhanced,size:'1024x1024',n:1}];
  let last='';for(const payload of variants){try{const j=await fetchJSON('https://api.openai.com/v1/images/generations',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+key},body:JSON.stringify(payload)},140000);const item=j?.data?.[0]||{},imageUrl=item.b64_json?'data:image/png;base64,'+item.b64_json:String(item.url||'');if(!imageUrl)throw new Error('OpenAI görsel API boş sonuç döndürdü');return {imageUrl,provider:`OpenAI · ${model}`,model}}catch(e){last=String(e?.message||e)}}throw new Error(last||'OpenAI görsel üretemedi');
}
async function imageGemini(prompt){
  const key=process.env.GEMINI_API_KEY;if(!key)throw new Error('GEMINI_API_KEY yok');
  const model=process.env.GEMINI_IMAGE_MODEL||'gemini-3.1-flash-image';
  const j=await fetchJSON('https://generativelanguage.googleapis.com/v1beta/interactions',{method:'POST',headers:{'Content-Type':'application/json','x-goog-api-key':key},body:JSON.stringify({model,input:[{type:'text',text:prompt}],response_format:{type:'image',mime_type:'image/png',aspect_ratio:'16:9',image_size:'1K'}})},140000);
  let data='',mime='image/png';
  for(const step of (j?.steps||[]))for(const c of (step?.content||[]))if(c?.type==='image'&&c?.data){data=c.data;mime=c.mime_type||mime;break}
  if(!data)throw new Error('Gemini görsel API boş sonuç döndürdü');
  return {imageUrl:`data:${mime};base64,${data}`,provider:`Gemini Görsel · ${model}`,model};
}
async function imageGrok(prompt){
  const key=process.env.GROK_API_KEY;if(!key)throw new Error('GROK_API_KEY yok');
  const model=process.env.GROK_IMAGE_MODEL||'grok-imagine-image-2.0';
  const j=await fetchJSON('https://api.x.ai/v1/images/generations',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+key},body:JSON.stringify({model,prompt,n:1,response_format:'url'})},140000);
  const item=j?.data?.[0]||{},imageUrl=String(item.url||'');if(!imageUrl)throw new Error('Grok görsel API boş sonuç döndürdü');
  return {imageUrl,provider:`Grok Imagine · ${model}`,model};
}
async function handleImage(body){
  const prompt=String(body?.prompt||'').trim();
  if(!prompt){const e=new Error('Görsel açıklaması boş.');e.status=400;throw e}
  const providers=[()=>imageGemini(prompt),()=>imageGrok(prompt),()=>imageOpenAI(prompt)];
  const errors=[];
  for(const run of providers){try{return await run()}catch(e){errors.push(String(e?.message||e))}}
  try{return {imageUrl:makePixelArtPng(prompt),provider:'ALLES Pixel Art · Yerel Yedek',model:'pixel-fallback',fallback:true}}
  catch(e){const err=new Error('Maalesef şu anda resmi oluşturamıyorum. '+errors.join(' | '));err.status=503;throw err}
}

const server=http.createServer(async(req,res)=>{
  const url=new URL(req.url,'http://localhost');
  if(url.pathname==='/favicon.ico'){res.writeHead(204);return res.end()}
  if(url.pathname==='/api/health'&&req.method==='GET')return sendJson(res,200,{ok:true,service:'ALLES AI'});
  if(url.pathname.startsWith('/api/')){
    const ip=String(req.headers['x-forwarded-for']||req.socket.remoteAddress||'unknown').split(',')[0].trim();
    if(!rateOkay(ip))return sendJson(res,429,{error:'Çok hızlı istek gönderildi. Bir dakika sonra tekrar dene.'});
    if(req.method!=='POST')return sendJson(res,405,{error:'Method not allowed'});
    try{
      const body=await readJson(req);
      if(url.pathname==='/api/chat')return sendJson(res,200,await handleChat(body));
      if(url.pathname==='/api/image')return sendJson(res,200,await handleImage(body));
      return sendJson(res,404,{error:'API bulunamadı'});
    }catch(e){
      const status=e?.message==='PAYLOAD_TOO_LARGE'?413:e?.message==='INVALID_JSON'?400:(e?.status||503);
      return sendJson(res,status,{error:String(e?.message||e)});
    }
  }
  if(req.method==='GET'||req.method==='HEAD')return sendHtml(res,req.method==='HEAD');
  res.writeHead(405,{'Content-Type':'text/plain; charset=utf-8'});res.end('Method not allowed');
});
server.listen(PORT,'0.0.0.0',()=>console.log(`ALLES AI running on ${PORT}`));
